const IMAGE_IDS = new Set(IMAGE_AVATARS.map((a) => a.id));

/** Every avatar that can render: images (hidden ones too) and SVGs not replaced by an image. */
export const ALL_AVATARS: readonly AvatarEntry[] = [
  ...IMAGE_AVATARS,
  ...SVG_AVATARS.filter((a) => !IMAGE_IDS.has(a.id)),
];

const VISIBLE_IMAGES = IMAGE_AVATARS.filter((a) => !a.hidden);

/**
 * The picker set. Owner artwork is the default set; the SVG recipes stay
 * registered for old rows and are offered only when no artwork is imported.
 */
export const AVATARS: readonly AvatarEntry[] = VISIBLE_IMAGES.length > 0 ? VISIBLE_IMAGES : SVG_AVATARS;

const BY_ID = new Map<string, AvatarEntry>(ALL_AVATARS.map((a) => [a.id, a]));

/** Ids offered in the picker (and by randomAvatarId). */
export const AVATAR_IDS: readonly string[] = AVATARS.map((a) => a.id);

export function getAvatar(id: string | null | undefined): AvatarEntry | undefined {
  return id ? BY_ID.get(id) : undefined;
}

export function isAvatarId(id: string | null | undefined): id is string {
  return !!id && BY_ID.has(id);
}

/** A random avatar id, different from `except` when there is a choice. */
export function randomAvatarId(except?: string | null, rand: () => number = Math.random): string {
  const pool = except && AVATAR_IDS.length > 1 ? AVATAR_IDS.filter((id) => id !== except) : AVATAR_IDS;
  return pool[Math.floor(rand() * pool.length) % pool.length];
}
